mapper.sql:
where ea.achievement_type = case when #{criteria.normalizedAchievementType} = 'LECTURE_ACHIEVEMENT' then 'LECTURE' else #{criteria.normalizedAchievementType} end
  and ea.deleted_yn = 'N'

    and ea.owner_user_id = #{ownerUserId}

mapper.select:
select count(*)
from function_permissions
where screen_id = #{screenId}
  and function_type = #{functionType}
  and permission_allowed = 'ALLOW'
  and role_code in
  #{role}

mapper.insert:
insert into education_achievement_management_values (
    achievement_id, management_item_code, value_text, created_by, updated_by
) values (
    #{achievementId}, #{managementItemCode}, #{valueText}, #{userId}, #{userId}
)

mapper.update:
update education_achievement_management_values
set value_text = #{valueText}, updated_by = #{userId}, updated_at = current_timestamp
where achievement_id = #{achievementId} and management_item_code = #{managementItemCode}

mapper.insert:
insert into student_guidance_details (
    achievement_id, student_name, guidance_start_date, guidance_end_date, student_count, created_by, updated_by
) values (
    #{achievementId}, #{studentName}, #{guidanceStartDate}, #{guidanceEndDate}, #{studentCount}, #{userId}, #{userId}
)

insert into degree_completion_student_details (
    achievement_id, degree_type, student_name, thesis_title, degree_awarded_on, created_by, updated_by
) values (
    #{achievementId}, #{degreeType}, #{studentName}, #{thesisTitle}, #{degreeAwardedOn}, #{userId}, #{userId}
)

mapper.select:
select count(*)
from business_status_transitions
where business_type = 'FACULTY_ACHIEVEMENT'
  and definition_version = 'CONFIRMED'
  and from_status_code = #{fromStatus}
  and to_status_code = #{toStatus}
  and executor_role_code in
  #{role}

mapper.insert:
insert into education_achievement_status_histories (
    achievement_id, previous_status, next_status, processed_by, reason, request_id
) values (
    #{achievementId}, #{previousStatus}, #{nextStatus}, #{processedBy}, #{reason}, #{requestId}
)

insert into data_change_histories (
    target_business, target_key, change_type, field_name, before_value, after_value,
    changed_by, change_reason, request_id
) values (
    'EDUCATION_ACHIEVEMENT', #{targetKey}, #{changeType}, #{fieldName}, #{beforeValue}, #{afterValue},
    #{changedBy}, #{changeReason}, #{requestId}
)
